<script setup lang="ts">
definePageMeta({middleware:'auth'});useHead({title:'تکمیل سفارش'});const{api}=useShopApi(),{cart,load}=useCart();await load();
const{data:options,refresh}=await useAsyncData('checkout-options',()=>api<any>('/checkout/options'));const{data:provinces}=await useAsyncData('provinces',()=>api<any[]>('/locations/provinces'));
const form=reactive({address_id:null as number|null,shipping_method_id:null as number|null,delivery_slot_id:null as number|null,discount_code:'',customer_note:''});const address=reactive({receiver_name:'',receiver_mobile:'',province_id:null as number|null,city_id:null as number|null,address:'',postal_code:'',is_default:true});const cities=ref<any[]>([]),discount=ref(0),loading=ref(false),error=ref('');
watch(()=>address.province_id,async id=>{address.city_id=null;cities.value=id?await api<any[]>(`/locations/cities?province_id=${id}`):[]});const money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v);
async function addAddress(){error.value='';try{const a=await api<any>('/addresses',{method:'POST',body:address});form.address_id=a.id;await refresh()}catch(e:any){error.value=e?.data?.message||Object.values(e?.data?.errors||{})[0]?.[0]||'ذخیره آدرس انجام نشد.'}}
async function checkDiscount(){try{const d=await api<any>('/checkout/discount',{method:'POST',body:{code:form.discount_code}});discount.value=d.amount}catch(e:any){error.value=e?.data?.message||'کد تخفیف معتبر نیست.'}}
async function submit(){loading.value=true;error.value='';try{const r=await api<any>('/checkout',{method:'POST',body:form});window.location.href=r.payment_url}catch(e:any){error.value=e?.data?.message||Object.values(e?.data?.errors||{})[0]?.[0]||'ثبت سفارش انجام نشد.'}finally{loading.value=false}}
</script>
<template><div class="mx-auto max-w-6xl px-4 py-10"><h1 class="text-2xl font-black">تکمیل سفارش</h1><form class="mt-7 grid gap-7 lg:grid-cols-[1fr_340px]" @submit.prevent="submit"><main class="space-y-5"><section class="rounded-2xl border bg-white p-5"><h2 class="font-black">آدرس تحویل</h2><div v-if="options?.addresses?.length" class="mt-4 grid gap-3 sm:grid-cols-2"><label v-for="a in options.addresses" :key="a.id" :class="['cursor-pointer rounded-xl border p-4',form.address_id===a.id?'border-brand-700 bg-brand-50':'']"><input v-model="form.address_id" type="radio" :value="a.id" class="ml-2 accent-brand-700"><b>{{a.title}}</b><p class="mt-2 text-xs leading-6 text-slate-500">{{a.province}}، {{a.city}}، {{a.address}}</p></label></div><div v-else class="mt-5 grid gap-3 sm:grid-cols-2"><input v-model="address.receiver_name" placeholder="نام تحویل‌گیرنده" class="h-11 rounded-xl border px-3"><input v-model="address.receiver_mobile" dir="ltr" placeholder="شماره موبایل" class="h-11 rounded-xl border px-3 text-left"><select v-model="address.province_id" class="h-11 rounded-xl border bg-white px-3"><option :value="null">انتخاب استان</option><option v-for="p in provinces" :key="p.id" :value="p.id">{{p.name}}</option></select><select v-model="address.city_id" :disabled="!address.province_id" class="h-11 rounded-xl border bg-white px-3 disabled:bg-slate-100"><option :value="null">انتخاب شهر</option><option v-for="c in cities" :key="c.id" :value="c.id">{{c.name}}</option></select><textarea v-model="address.address" placeholder="نشانی کامل" class="rounded-xl border p-3 sm:col-span-2"/><input v-model="address.postal_code" dir="ltr" placeholder="کد پستی ۱۰ رقمی" class="h-11 rounded-xl border px-3 text-left"><button type="button" :disabled="!address.city_id" class="rounded-xl bg-brand-50 font-bold text-brand-700 disabled:opacity-40" @click="addAddress">ذخیره آدرس</button></div></section><section class="rounded-2xl border bg-white p-5"><h2 class="font-black">روش ارسال</h2><div class="mt-4 space-y-3"><label v-for="m in options?.shipping_methods" :key="m.id" :class="['flex cursor-pointer justify-between rounded-xl border p-4',form.shipping_method_id===m.id?'border-brand-700 bg-brand-50':'']"><span><input v-model="form.shipping_method_id" type="radio" :value="m.id" class="ml-2">{{m.title}}</span><b>{{m.calculated_cost?money(m.calculated_cost)+' تومان':'رایگان'}}</b></label></div></section><section v-if="options?.delivery_slots?.length" class="rounded-2xl border bg-white p-5"><h2 class="font-black">زمان تحویل</h2><div class="mt-4 flex gap-3 overflow-auto"><label v-for="s in options.delivery_slots" :key="s.id" :class="['shrink-0 cursor-pointer rounded-xl border p-4 text-sm',form.delivery_slot_id===s.id?'border-brand-700 bg-brand-50':'']"><input v-model="form.delivery_slot_id" type="radio" :value="s.id" class="ml-2">{{new Date(s.date).toLocaleDateString('fa-IR')}}<p class="mt-2 text-xs text-slate-400">{{s.starts_at}} تا {{s.ends_at}}</p></label></div></section></main><aside class="h-fit rounded-2xl border bg-white p-5 shadow-soft"><h2 class="font-black">خلاصه سفارش</h2><div class="mt-5 flex gap-2"><input v-model="form.discount_code" dir="ltr" placeholder="کد تخفیف" class="h-10 min-w-0 flex-1 rounded-xl border px-3 text-left"><button type="button" class="rounded-xl border px-3 text-sm font-bold" @click="checkDiscount">اعمال</button></div><div class="mt-6 space-y-3 text-sm"><div class="flex justify-between"><span>مبلغ کالاها</span><span>{{money(cart.subtotal)}} تومان</span></div><div v-if="discount" class="flex justify-between text-emerald-700"><span>تخفیف</span><span>− {{money(discount)}} تومان</span></div></div><p v-if="error" class="mt-4 rounded-xl bg-rose-50 p-3 text-xs leading-6 text-rose-700">{{error}}</p><button :disabled="loading||!form.address_id||!form.shipping_method_id" class="mt-5 w-full rounded-xl bg-brand-700 py-4 font-black text-white disabled:bg-slate-300">{{loading?'در حال انتقال…':'پرداخت و ثبت سفارش'}}</button></aside></form></div></template>
